diff --git a/config/syslog/syslogconf_test.go b/config/syslog/syslogconf_test.go
new file mode 100644
index 0000000..c47bc23
--- /dev/null
+++ b/config/syslog/syslogconf_test.go
@@ -0,0 +1,28 @@
+//go:build !windows
+
+package syslog
+
+import "testing"
+
+func TestConfValidate(t *testing.T) {
+	tests := []struct {
+		name string
+		conf Conf
+		want int
+	}{
+		{"disabled", Conf{Protocol: "bad", Port: "bad", Severity: "bad", Facility: "bad"}, 0},
+		{"defaults", Conf{Enabled: true}, 0},
+		{"tcp", Conf{Enabled: true, Protocol: "tcp", Port: "5140"}, 0},
+		{"udp", Conf{Enabled: true, Protocol: "udp", Port: "12345", Severity: "emerg", Facility: "user"}, 0},
+		{"protocol", Conf{Enabled: true, Protocol: "foo", Port: "514"}, 1},
+		{"protocol and port", Conf{Enabled: true, Protocol: "invalid", Port: "-1"}, 2},
+		{"all core fields", Conf{Enabled: true, Protocol: "invalid", Port: "invalid", Severity: "invalid", Facility: "invalid"}, 4},
+	}
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			if got := len(tt.conf.Validate()); got != tt.want {
+				t.Errorf("Validate() returned %d errors, want %d", got, tt.want)
+			}
+		})
+	}
+}
